query:
-- Ajoute des aides interactives ciblées aux cours de SVT déjà actifs, sans réécrire leur contenu.
do $add_svt_anatomy_biology_interactives_do$
declare
  brain_count integer;
  protein_count integer;
  immune_count integer;
  neuron_count integer;
  heart_count integer;
begin
  select count(*) into brain_count from public.lessons lesson join public.chapters chapter on chapter.id = lesson.chapter_id join public.course_subject_offerings offering on offering.id = chapter.subject_offering_id join public.subjects subject on subject.id = offering.subject_id join public.levels level on level.id = offering.level_id join public.series series on series.id = offering.series_id where subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name in ('A1', 'A2') and lesson.title = 'Leçon 2 : L’activité cérébrale chez l’Homme.' and lesson.is_active and not lesson.is_test_data and lesson.content not like '%:::anatomy-diagram-brain%';
  select count(*) into protein_count from public.lessons lesson join public.chapters chapter on chapter.id = lesson.chapter_id join public.course_subject_offerings offering on offering.id = chapter.subject_offering_id join public.subjects subject on subject.id = offering.subject_id join public.levels level on level.id = offering.level_id join public.series series on series.id = offering.series_id where subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name in ('A1', 'A2') and lesson.title = 'Leçon : L’utilisation des nutriments : la biosynthèse des protéines.' and lesson.is_active and not lesson.is_test_data and lesson.content not like '%:::biology-animation-protein-synthesis%';
  select count(*) into immune_count from public.lessons lesson join public.chapters chapter on chapter.id = lesson.chapter_id join public.course_subject_offerings offering on offering.id = chapter.subject_offering_id join public.subjects subject on subject.id = offering.subject_id join public.levels level on level.id = offering.level_id join public.series series on series.id = offering.series_id where subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name = 'C' and lesson.title = 'Leçon 1 : Le système de défense de l’organisme.' and lesson.is_active and not lesson.is_test_data and lesson.content not like '%:::biology-animation-immune-response%';
  select count(*) into neuron_count from public.lessons lesson join public.chapters chapter on chapter.id = lesson.chapter_id join public.course_subject_offerings offering on offering.id = chapter.subject_offering_id join public.subjects subject on subject.id = offering.subject_id join public.levels level on level.id = offering.level_id join public.series series on series.id = offering.series_id where subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name = 'D' and lesson.title = 'Leçon 2 : Le fonctionnement du tissu nerveux.' and lesson.is_active and not lesson.is_test_data and lesson.content not like '%:::anatomy-diagram-neuron%';
  select count(*) into heart_count from public.lessons lesson join public.chapters chapter on chapter.id = lesson.chapter_id join public.course_subject_offerings offering on offering.id = chapter.subject_offering_id join public.subjects subject on subject.id = offering.subject_id join public.levels level on level.id = offering.level_id join public.series series on series.id = offering.series_id where subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name = 'D' and lesson.title = 'Leçon 4 : Le fonctionnement du cœur.' and lesson.is_active and not lesson.is_test_data and lesson.content not like '%:::anatomy-diagram-heart%';
  if brain_count <> 2 or protein_count <> 2 or immune_count <> 1 or neuron_count <> 1 or heart_count <> 1 then raise exception 'Ajout des aides SVT refusé : cibles attendues (2,2,1,1,1), trouvées (%,%,%,%,%).', brain_count, protein_count, immune_count, neuron_count, heart_count; end if;
  update public.lessons lesson set content = regexp_replace(lesson.content, '\s*$', '') || E'\n\n:::anatomy-diagram-brain\n\n:::biology-animation-neural-signal' from public.chapters chapter, public.course_subject_offerings offering, public.subjects subject, public.levels level, public.series series where lesson.chapter_id = chapter.id and chapter.subject_offering_id = offering.id and offering.subject_id = subject.id and offering.level_id = level.id and offering.series_id = series.id and subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name in ('A1', 'A2') and lesson.title = 'Leçon 2 : L’activité cérébrale chez l’Homme.' and lesson.is_active and not lesson.is_test_data;
  update public.lessons lesson set content = regexp_replace(lesson.content, '\s*$', '') || E'\n\n:::biology-animation-protein-synthesis' from public.chapters chapter, public.course_subject_offerings offering, public.subjects subject, public.levels level, public.series series where lesson.chapter_id = chapter.id and chapter.subject_offering_id = offering.id and offering.subject_id = subject.id and offering.level_id = level.id and offering.series_id = series.id and subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name in ('A1', 'A2') and lesson.title = 'Leçon : L’utilisation des nutriments : la biosynthèse des protéines.' and lesson.is_active and not lesson.is_test_data;
  update public.lessons lesson set content = regexp_replace(lesson.content, '\s*$', '') || E'\n\n:::biology-animation-immune-response' from public.chapters chapter, public.course_subject_offerings offering, public.subjects subject, public.levels level, public.series series where lesson.chapter_id = chapter.id and chapter.subject_offering_id = offering.id and offering.subject_id = subject.id and offering.level_id = level.id and offering.series_id = series.id and subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name = 'C' and lesson.title = 'Leçon 1 : Le système de défense de l’organisme.' and lesson.is_active and not lesson.is_test_data;
  update public.lessons lesson set content = regexp_replace(lesson.content, '\s*$', '') || E'\n\n:::anatomy-diagram-neuron\n\n:::biology-animation-neural-signal' from public.chapters chapter, public.course_subject_offerings offering, public.subjects subject, public.levels level, public.series series where lesson.chapter_id = chapter.id and chapter.subject_offering_id = offering.id and offering.subject_id = subject.id and offering.level_id = level.id and offering.series_id = series.id and subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name = 'D' and lesson.title = 'Leçon 2 : Le fonctionnement du tissu nerveux.' and lesson.is_active and not lesson.is_test_data;
  update public.lessons lesson set content = regexp_replace(lesson.content, '\s*$', '') || E'\n\n:::anatomy-diagram-heart' from public.chapters chapter, public.course_subject_offerings offering, public.subjects subject, public.levels level, public.series series where lesson.chapter_id = chapter.id and chapter.subject_offering_id = offering.id and offering.subject_id = subject.id and offering.level_id = level.id and offering.series_id = series.id and subject.name = 'Sciences de la Vie et de la Terre' and level.name = 'Terminale' and series.name = 'D' and lesson.title = 'Leçon 4 : Le fonctionnement du cœur.' and lesson.is_active and not lesson.is_test_data;
end $add_svt_anatomy_biology_interactives_do$;
